        int right = arr.length - 1;

        // Continue swapping until both pointers meet
        while (left < right) {

            // Store left value temporarily before swapping
            int temp = arr[left];

            // Move right element to left position
            arr[left] = arr[right];

            // Move stored left element to right position
            arr[right] = temp;

            // Move left pointer forward
            left++;

            // Move right pointer backward
            right--;
        }
    }
