        }

        return water;
    }
}

class Solution {
    public int trap(int[] height) {

        // Pointer starting from left side
        int left = 0;

        // Pointer starting from right side
        int right = height.length - 1;

        // Store maximum height seen from left side
        int leftMax = 0;

        // Store maximum height seen from right side
        int rightMax = 0;

        // Store total trapped water
        int water = 0;

        // Process elements until pointers meet
        while (left < right) {

            // If left bar is smaller, left side decides water level
            if (height[left] < height[right]) {

                // Update left maximum boundary
                if (height[left] >= leftMax) {
                    leftMax = height[left];
                } else {

                    // Water trapped is difference between left max and current height
                    water += leftMax - height[left];
                }

                // Move left pointer forward
                left++;

            } else {

                // Update right maximum boundary
                if (height[right] >= rightMax) {
                    rightMax = height[right];
                } else {

                    // Water trapped is difference between right max and current height
                    water += rightMax - height[right];
                }

                // Move right pointer backward
                right--;
            }
        }

        // Return total trapped water
        return water;
    }
}

class Solution {
    public boolean isPalindrome(String s) {

        // Build cleaned string with only alphanumeric characters
        StringBuilder cleaned = new StringBuilder();

        for (char c : s.toCharArray()) {
            if (Character.isLetterOrDigit(c)) {
                cleaned.append(Character.toLowerCase(c));
            }
        }

        // Compare with reversed string
        String reversed = cleaned.reverse().toString();
        return cleaned.toString().equals(reversed);
    }
}

class Solution {
    public boolean isPalindrome(String s) {

        // Pointer starting from beginning
        int left = 0;

        // Pointer starting from end
        int right = s.length() - 1;

        // Compare characters from both sides
        while (left < right) {

            // Skip non-alphanumeric characters from left side
            while (left < right && !Character.isLetterOrDigit(s.charAt(left))) {
                left++;
            }

            // Skip non-alphanumeric characters from right side
            while (left < right && !Character.isLetterOrDigit(s.charAt(right))) {
                right--;
            }

            // Convert both characters to lowercase and compare
            if (Character.toLowerCase(s.charAt(left)) != Character.toLowerCase(s.charAt(right))) {
                return false;
            }

            // Move pointers towards center
            left++;
            right--;
        }

        // String is palindrome
        return true;
    }
}

class Solution {
    public int removeDuplicates(int[] nums) {

        // Use a set to store unique elements
        Set<Integer> unique = new LinkedHashSet<>();

        for (int num : nums) {
            unique.add(num);
        }

        // Copy back to original array
        int index = 0;
        for (int num : unique) {
            nums[index++] = num;
        }

        return unique.size();
    }
}

class Solution {
    public int removeDuplicates(int[] nums) {

        // Position where next unique element will be stored
        int slow = 1;

        // Traverse array from second element
        for (int fast = 1; fast < nums.length; fast++) {

            // If current element is different from previous unique element
            if (nums[fast] != nums[fast - 1]) {

                // Place unique element at slow pointer position
                nums[slow] = nums[fast];

                // Move slow pointer forward
                slow++;
            }
        }

        // Return count of unique elements
        return slow;
    }
}

