class Solution {
    public int[] sortedSquares(int[] nums) {

        // Result array to store sorted squares
        int[] result = new int[nums.length];

        // Pointer at beginning
        int left = 0;

        // Pointer at end
        int right = nums.length - 1;

        // Fill result from the end because largest values come first
        int index = nums.length - 1;

        while (left <= right) {

            // Square value from left side
            int leftSquare = nums[left] * nums[left];

            // Square value from right side
            int rightSquare = nums[right] * nums[right];

            // Place larger square at current index
            if (leftSquare > rightSquare) {
                result[index] = leftSquare;
                left++;
            } else {
                result[index] = rightSquare;
                right--;
            }

            // Move result position backward
            index--;
        }

        return result;
    }
}

class Solution {
    public boolean backspaceCompare(String s, String t) {

        int i = s.length() - 1;
        int j = t.length() - 1;

        while (i >= 0 || j >= 0) {

            i = getNextIndex(s, i);
            j = getNextIndex(t, j);

            // Both strings finished
            if (i < 0 && j < 0) return true;

            // One string finished earlier
            if (i < 0 || j < 0) return false;

            // Characters do not match
            if (s.charAt(i) != t.charAt(j)) return false;

            i--;
            j--;
        }

        return true;
    }

    private int getNextIndex(String str, int index) {

        int backspace = 0;

        while (index >= 0) {

            if (str.charAt(index) == '#') {
                backspace++;
            } else if (backspace > 0) {
                backspace--;
            } else {
                break;
            }

            index--;
        }

        return index;
    }
}

class Solution {
    public int threeSumClosest(int[] nums, int target) {

        // Sort array to apply two pointer technique
        Arrays.sort(nums);

        // Store closest sum found
        int closest = nums[0] + nums[1] + nums[2];

        // Fix first element
        for (int i = 0; i < nums.length - 2; i++) {

            // Two pointers for remaining elements
            int left = i + 1;
            int right = nums.length - 1;

            while (left < right) {

                // Current three number sum
                int sum = nums[i] + nums[left] + nums[right];

                // Update closest answer
                if (Math.abs(target - sum) < Math.abs(target - closest)) {
                    closest = sum;
                }

                // Move pointers according to sum
                if (sum < target) {
                    left++;
                } else {
                    right--;
                }
            }
        }

        return closest;
    }
}

class Solution {
    public void sortColors(int[] nums) {

        // Pointer for position of next zero
        int low = 0;

        // Current scanning pointer
        int mid = 0;

        // Pointer for position of next two
        int high = nums.length - 1;

        while (mid <= high) {

            // Current value is 0
            if (nums[mid] == 0) {

                // Swap zero to low region
                int temp = nums[low];
                nums[low] = nums[mid];
                nums[mid] = temp;

                low++;
                mid++;
            }

            // Current value is 1
            else if (nums[mid] == 1) {
                mid++;
            }

            // Current value is 2
            else {
                int temp = nums[mid];
                nums[mid] = nums[high];
                nums[high] = temp;

                high--;
            }
        }
    }
}

class Solution {
    public double findMaxAverage(int[] nums, int k) {

        // Store sum of current window
        int windowSum = 0;

        // Calculate sum of first k elements
        for (int i = 0; i < k; i++) {
            windowSum += nums[i];
        }

        // Store maximum sum found
        int maxSum = windowSum;

        // Slide window from k to end
        for (int i = k; i < nums.length; i++) {

            // Remove element leaving the window
            windowSum -= nums[i - k];

            // Add new element entering the window
            windowSum += nums[i];

            // Update maximum window sum
            maxSum = Math.max(maxSum, windowSum);
        }

        // Convert maximum sum into average
        return (double) maxSum / k;
    }
}

class Solution {
    public int lengthOfLongestSubstring(String s) {

        // Store last index of characters
        Map<Character, Integer> map = new HashMap<>();

        // Left boundary of window
        int left = 0;

        // Store maximum window length
        int maxLength = 0;

        // Expand window using right pointer
        for (int right = 0; right < s.length(); right++) {

            char current = s.charAt(right);

            // If character exists inside current window, move left
            if (map.containsKey(current)) {
                left = Math.max(left, map.get(current) + 1);
            }

            // Store current character position
            map.put(current, right);

            // Update maximum length
            maxLength = Math.max(maxLength, right - left + 1);
        }

        return maxLength;
    }
}

class Solution {
    public int minSubArrayLen(int target, int[] nums) {

        // Left boundary of window
        int left = 0;

        // Current window sum
        int sum = 0;

        // Store minimum length found
        int minLength = Integer.MAX_VALUE;

        // Expand window using right pointer
        for (int right = 0; right < nums.length; right++) {

            // Add current element to window
            sum += nums[right];

            // Shrink window while condition is satisfied
            while (sum >= target) {

                // Update smallest valid window
                minLength = Math.min(minLength, right - left + 1);

                // Remove left element
                sum -= nums[left];

                // Move left pointer forward
                left++;
            }
        }

        return minLength == Integer.MAX_VALUE ? 0 : minLength;
    }
}

class Solution {
    public int characterReplacement(String s, int k) {

        // Store character frequencies
        int[] freq = new int[26];

        // Left pointer of window
        int left = 0;

        // Maximum frequency inside current window
        int maxFreq = 0;

        // Store maximum window size
        int answer = 0;

        // Expand window
        for (int right = 0; right < s.length(); right++) {

            // Increase current character count
            freq[s.charAt(right) - 'A']++;

            // Update highest frequency character
            maxFreq = Math.max(maxFreq, freq[s.charAt(right) - 'A']);

            // Calculate replacements needed
            while ((right - left + 1) - maxFreq > k) {

                // Remove left character
                freq[s.charAt(left) - 'A']--;

                // Shrink window
                left++;
            }

            // Update answer
            answer = Math.max(answer, right - left + 1);
        }

        return answer;
    }
}

class Solution {
    public boolean checkInclusion(String s1, String s2) {

        // If pattern is larger than text, impossible
        if (s1.length() > s2.length()) return false;

        // Frequency of characters in pattern
        int[] pattern = new int[26];

        for (char c : s1.toCharArray()) {
            pattern[c - 'a']++;
        }

        // Frequency of current window
        int[] window = new int[26];

        int left = 0;

        // Expand window
        for (int right = 0; right < s2.length(); right++) {

            window[s2.charAt(right) - 'a']++;

            // Keep window size equal to s1 length
            if (right - left + 1 > s1.length()) {
                window[s2.charAt(left) - 'a']--;
                left++;
            }

            // Compare frequencies
            if (Arrays.equals(pattern, window)) {
                return true;
            }
        }

        return false;
    }
}

class Solution {
    public List<Integer> findAnagrams(String s, String p) {

        List<Integer> result = new ArrayList<>();

        // Store pattern frequency
        int[] pattern = new int[26];
        for (char c : p.toCharArray()) {
            pattern[c - 'a']++;
        }

        int[] window = new int[26];
        int left = 0;

        // Expand window
        for (int right = 0; right < s.length(); right++) {

            window[s.charAt(right) - 'a']++;

            // Remove extra characters from window
            if (right - left + 1 > p.length()) {
                window[s.charAt(left) - 'a']--;
                left++;
            }

            // Current window is anagram
            if (Arrays.equals(pattern, window)) {
                result.add(left);
            }
        }

        return result;
    }
}

class Solution {
    public int maxVowels(String s, int k) {

        // Store current vowel count
        int count = 0;

        // Store maximum vowels found
        int maxCount = 0;

        // Count vowels in first window
        for (int i = 0; i < k; i++) {
            if (isVowel(s.charAt(i))) {
                count++;
            }
        }

        maxCount = count;

        // Slide window
        for (int i = k; i < s.length(); i++) {

            // Add new character entering window
            if (isVowel(s.charAt(i))) {
                count++;
            }

            // Remove character leaving window
            if (isVowel(s.charAt(i - k))) {
                count--;
            }

            // Update answer
            maxCount = Math.max(maxCount, count);
        }

        return maxCount;
    }

    private boolean isVowel(char c) {
        return c=='a'||c=='e'||c=='i'||c=='o'||c=='u';
    }
}

class Solution {
    public int longestSubarray(int[] nums) {

        // Left boundary
        int left = 0;

        // Count zeros in window
        int zeros = 0;

        // Store best answer
        int answer = 0;

        // Expand window
        for (int right = 0; right < nums.length; right++) {

            // Count zero entering window
            if (nums[right] == 0) {
                zeros++;
            }

            // Keep at most one zero
            while (zeros > 1) {
                if (nums[left] == 0) {
                    zeros--;
                }
                left++;
            }

            // Subtract one because one element must be deleted
            answer = Math.max(answer, right - left);
        }

        return answer;
    }
}

class Solution {
    public int longestOnes(int[] nums, int k) {

        // Left boundary of window
        int left = 0;

        // Count zeros inside window
        int zeros = 0;

        // Store maximum window length
        int answer = 0;

        // Expand window using right pointer
        for (int right = 0; right < nums.length; right++) {

            // Add zero count
            if (nums[right] == 0) {
                zeros++;
            }

            // Shrink window if more than k flips needed
            while (zeros > k) {

                if (nums[left] == 0) {
                    zeros--;
                }

                left++;
            }

            // Current window is valid
            answer = Math.max(answer, right - left + 1);
        }

        return answer;
    }
}

class Solution {
    public int totalFruit(int[] fruits) {

        // Store fruit frequency in window
        Map<Integer, Integer> map = new HashMap<>();

        // Left pointer
        int left = 0;

        // Maximum valid window length
        int answer = 0;

        // Expand window
        for (int right = 0; right < fruits.length; right++) {

            // Add current fruit
            map.put(fruits[right], map.getOrDefault(fruits[right], 0) + 1);

            // Shrink when more than two fruit types exist
            while (map.size() > 2) {

                map.put(fruits[left], map.get(fruits[left]) - 1);

                // Remove fruit type completely
                if (map.get(fruits[left]) == 0) {
                    map.remove(fruits[left]);
                }

                left++;
            }

            // Update answer
            answer = Math.max(answer, right - left + 1);
        }

        return answer;
    }
}

