class Solution {
    public int pivotIndex(int[] nums) {

        // Calculate total array sum
        int total = 0;
        for (int num : nums) {
            total += num;
        }

        // Store left side sum
        int leftSum = 0;

        // Check every index
        for (int i = 0; i < nums.length; i++) {

            // Right sum = total - left sum - current value
            int rightSum = total - leftSum - nums[i];

            if (leftSum == rightSum) {
                return i;
            }

            // Add current value for next index
            leftSum += nums[i];
        }

        return -1;
    }
}

class NumArray {

