        for (int i = 0; i < nums.length; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }
    }

    public int sumRange(int left, int right) {

        // Sum between left and right
        // prefix[right+1] contains sum till right
        // prefix[left] removes elements before left
        return prefix[right + 1] - prefix[left];
    }
}

class Solution {
    public int subarraySum(int[] nums, int k) {

        // Store prefix sum frequency
        Map<Integer, Integer> map = new HashMap<>();

        // Empty prefix sum before starting
        map.put(0, 1);

        // Running prefix sum
        int prefixSum = 0;

        // Count valid subarrays
        int count = 0;

        for (int num : nums) {

            // Add current number to prefix sum
            prefixSum += num;

            // Check if required previous prefix exists
            if (map.containsKey(prefixSum - k)) {
                count += map.get(prefixSum - k);
            }

            // Store current prefix sum frequency
            map.put(prefixSum, map.getOrDefault(prefixSum, 0) + 1);
        }

        return count;
    }
}

class Solution {
    public boolean checkSubarraySum(int[] nums, int k) {

        // Store first index of each remainder
        Map<Integer, Integer> map = new HashMap<>();

        // Prefix sum before array starts
        map.put(0, -1);

        // Running prefix sum
        int sum = 0;

        for (int i = 0; i < nums.length; i++) {

            // Add current value
            sum += nums[i];

            // Calculate remainder
            int remainder = sum % k;

            // If remainder appeared before, subarray sum is divisible by k
            if (map.containsKey(remainder)) {

                // Check length should be at least 2
                if (i - map.get(remainder) >= 2) {
                    return true;
                }
            } else {

                // Store only first occurrence
                map.put(remainder, i);
            }
        }

        return false;
    }
}

class Solution {
    public int maxSubArrayLen(int[] nums, int k) {

        // Store first index of prefix sums
        Map<Integer, Integer> map = new HashMap<>();

        // Prefix sum before starting
        map.put(0, -1);

        // Current prefix sum
        int sum = 0;

        // Maximum length answer
        int maxLength = 0;

        for (int i = 0; i < nums.length; i++) {

            // Add current element
            sum += nums[i];

            // Check required previous prefix sum
            if (map.containsKey(sum - k)) {

                // Calculate subarray length
                maxLength = Math.max(maxLength, i - map.get(sum - k));
            }

            // Store only first occurrence
            if (!map.containsKey(sum)) {
                map.put(sum, i);
            }
        }

        return maxLength;
    }
}

class Solution {
