class Solution {
    public int maxProduct(int[] nums) {

        // Maximum product ending here
        int maxProduct = nums[0];

        // Minimum product ending here
        int minProduct = nums[0];

        // Final answer
        int answer = nums[0];

        for (int i = 1; i < nums.length; i++) {

            // Store previous values before update
            int current = nums[i];

            int tempMax = Math.max(current, Math.max(maxProduct * current, minProduct * current));
            int tempMin = Math.min(current, Math.min(maxProduct * current, minProduct * current));

            // Update maximum and minimum products
            maxProduct = tempMax;
            minProduct = tempMin;

            // Update answer
            answer = Math.max(answer, maxProduct);
        }

        return answer;
    }
}

class Solution {
    public int maxSubarraySumCircular(int[] nums) {

        // Track total array sum
        int totalSum = 0;

        // Normal Kadane variables
        int currentMax = 0;
        int maxSum = nums[0];

        // Minimum Kadane variables
        int currentMin = 0;
        int minSum = nums[0];

        for (int num : nums) {

            // Add current value to total
            totalSum += num;

            // Maximum subarray calculation
            currentMax = Math.max(num, currentMax + num);
            maxSum = Math.max(maxSum, currentMax);

            // Minimum subarray calculation
            currentMin = Math.min(num, currentMin + num);
            minSum = Math.min(minSum, currentMin);
        }

        // If all numbers are negative, circular calculation fails
        if (maxSum < 0) {
            return maxSum;
        }

        // Compare normal and circular maximum
        return Math.max(maxSum, totalSum - minSum);
    }
}

class Solution {
    public long maxAlternatingSum(int[] nums) {

        // Best sum when current position is positive addition
        long even = 0;

        // Best sum when current position is subtraction
        long odd = 0;

        for (int num : nums) {

            // Store previous value before updating
            long previousEven = even;

            // Choose current number as positive or keep old value
            even = Math.max(previousEven, odd + num);

            // Choose current number as negative position
            odd = Math.max(odd, previousEven - num);
        }

        return even;
    }
}

class Solution {
    public int maxSumRectangle(int[][] matrix) {

        int rows = matrix.length;
        int cols = matrix[0].length;

        int answer = Integer.MIN_VALUE;

        // Fix starting column
        for (int left = 0; left < cols; left++) {

            int[] temp = new int[rows];

            // Expand ending column
            for (int right = left; right < cols; right++) {

                // Add current column values
                for (int row = 0; row < rows; row++) {
                    temp[row] += matrix[row][right];
                }

                // Apply Kadane on compressed array
                int current = temp[0];
                int best = temp[0];

                for (int i = 1; i < rows; i++) {
                    current = Math.max(temp[i], current + temp[i]);
                    best = Math.max(best, current);
                }

                answer = Math.max(answer, best);
            }
        }

        return answer;
    }
}

class Solution {
    public int maximumDifference(int[] nums) {

        // Smallest value seen so far
        int minimum = nums[0];

        // Store maximum difference
        int answer = -1;

        for (int i = 1; i < nums.length; i++) {

            // Calculate possible difference
            if (nums[i] > minimum) {
                answer = Math.max(answer, nums[i] - minimum);
            }

            // Update minimum value
            minimum = Math.min(minimum, nums[i]);
        }

        return answer;
    }
}

