class Solution {
    public void reverseString(char[] s) {

        // Left pointer starts from beginning
        int left = 0;

        // Right pointer starts from end
        int right = s.length - 1;

        // Continue until both pointers cross
        while (left < right) {

            // Store left character temporarily before swapping
            char temp = s[left];

            // Move right character to left position
            s[left] = s[right];

            // Move stored left character to right position
            s[right] = temp;

            // Move pointers towards center
            left++;
            right--;
        }
    }
}

