        boolean changed = true;

        while (changed) {
            changed = false;

            for (int i = 0; i < result.length() - 1; i++) {

                // Check adjacent duplicate characters
                if (result.charAt(i) == result.charAt(i + 1)) {

                    // Remove both characters
                    result.delete(i, i + 2);

