class Solution {
    public boolean isAnagram(String s, String t) {

        // Different lengths cannot have same frequency
        if (s.length() != t.length()) {
            return false;
        }

        // Store frequency of 26 lowercase characters
        int[] count = new int[26];

        // Increase count for s and decrease for t
        for (int i = 0; i < s.length(); i++) {
            count[s.charAt(i) - 'a']++;
            count[t.charAt(i) - 'a']--;
        }

        // If any value is not zero, frequencies differ
        for (int value : count) {
            if (value != 0) {
                return false;
            }
        }

        return true;
    }
}

class Solution {
