        // Store required character frequency
        int[] target = new int[26];

        for(char ch : p.toCharArray()) {
            target[ch - 'a']++;
        }

        int[] window = new int[26];
        int left = 0;

        for(int right = 0; right < s.length(); right++) {

            // Add current character into window
            window[s.charAt(right) - 'a']++;

            // Maintain window size equal to p length
            if(right - left + 1 > p.length()) {
                window[s.charAt(left) - 'a']--;
                left++;
            }

            // Compare frequency arrays
            if(Arrays.equals(window, target)) {
                answer.add(left);
            }
        }

        return answer;
    }
}

class Solution {
    public String minWindow(String s, String t) {

        int[] need = new int[128];

        // Store required characters
        for(char ch : t.toCharArray()) {
            need[ch]++;
        }

        int left = 0;
        int count = t.length();
        int start = 0;
        int minLength = Integer.MAX_VALUE;

        for(int right = 0; right < s.length(); right++) {

            // If character is needed, decrease count
            if(need[s.charAt(right)] > 0) {
                count--;
            }

            need[s.charAt(right)]--;

            // Valid window found
            while(count == 0) {

                if(right - left + 1 < minLength) {
                    start = left;
                    minLength = right - left + 1;
                }

                need[s.charAt(left)]++;

                if(need[s.charAt(left)] > 0) {
                    count++;
                }

                left++;
            }
        }

        return minLength == Integer.MAX_VALUE ? "" : s.substring(start,start+minLength);
    }
}

