class Solution {
    public String longestPalindrome(String s) {

        int start = 0;
        int end = 0;

        for(int i = 0; i < s.length(); i++) {

            // Odd length palindrome
            int len1 = expand(s, i, i);

            // Even length palindrome
            int len2 = expand(s, i, i + 1);

            int len = Math.max(len1, len2);

            if(len > end - start) {
                start = i - (len - 1) / 2;
                end = i + len / 2;
            }
        }

        return s.substring(start, end + 1);
    }

    private int expand(String s, int left, int right) {

        while(left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
            left--;
            right++;
        }

        return right - left - 1;
    }
}

class Trie {

    // Node represents one character
    class Node {
        Node[] children = new Node[26];
        boolean isEnd;
    }

    Node root;

    public Trie() {
        // Create empty root node
        root = new Node();
    }

    public void insert(String word) {

        Node current = root;

        // Traverse every character
        for(char ch : word.toCharArray()) {

            int index = ch - 'a';

            // Create node if character does not exist
            if(current.children[index] == null) {
                current.children[index] = new Node();
            }

            current = current.children[index];
        }

        // Mark complete word
        current.isEnd = true;
    }

    public boolean search(String word) {

        Node node = findNode(word);

        return node != null && node.isEnd;
    }

    public boolean startsWith(String prefix) {
        return findNode(prefix) != null;
    }

    private Node findNode(String word) {

        Node current = root;

        for(char ch : word.toCharArray()) {

            int index = ch - 'a';

            if(current.children[index] == null) {
                return null;
            }

            current = current.children[index];
        }

        return current;
    }
}

class WordDictionary {

    class Node {
        Node[] children = new Node[26];
        boolean isEnd;
    }

    Node root;

    public WordDictionary() {
        root = new Node();
    }

    public void addWord(String word) {

        Node current = root;

        for(char ch : word.toCharArray()) {
            int index = ch - 'a';

            if(current.children[index] == null) {
                current.children[index] = new Node();
            }

            current = current.children[index];
        }

        current.isEnd = true;
    }

    public boolean search(String word) {
        return dfs(word, 0, root);
    }

    private boolean dfs(String word, int index, Node node) {

        if(index == word.length()) {
            return node.isEnd;
        }

        char ch = word.charAt(index);

        if(ch == '.') {

            // Try every possible character
            for(Node child : node.children) {
                if(child != null && dfs(word, index + 1, child)) {
                    return true;
                }
            }

            return false;
        }

        int pos = ch - 'a';

        if(node.children[pos] == null) {
            return false;
        }

        return dfs(word, index + 1, node.children[pos]);
    }
}

class Solution {

    class Node {
        Node[] children = new Node[26];
        String word;
    }

    Node root = new Node();

    public String replaceWords(List<String> dictionary, String sentence) {

        // Build Trie from dictionary roots
        for(String rootWord : dictionary) {
            insert(rootWord);
        }

        StringBuilder result = new StringBuilder();

        for(String word : sentence.split(" ")) {

            // Find shortest matching root
            String replacement = search(word);

            result.append(replacement).append(" ");
        }

        return result.toString().trim();
    }

    private void insert(String word) {

        Node current = root;

        for(char ch : word.toCharArray()) {
            int index = ch - 'a';

            if(current.children[index] == null) {
                current.children[index] = new Node();
            }

            current = current.children[index];
        }

        // Store complete root word
        current.word = word;
    }

    private String search(String word) {

        Node current = root;

        for(char ch : word.toCharArray()) {

            int index = ch - 'a';

            if(current.children[index] == null) {
                return word;
            }

            current = current.children[index];

            // Shortest root found
            if(current.word != null) {
                return current.word;
            }
        }

        return word;
    }
}

class Solution {

    class Node {
        Node[] children = new Node[26];
        int count;
    }

    public String longestCommonPrefix(String[] strs) {

        Node root = new Node();

        // Insert every string
        for(String str : strs) {
            insert(root, str);
        }

        StringBuilder ans = new StringBuilder();
        Node current = root;

        // Traverse while only one path exists
        while(current.count == 1) {

            for(int i = 0; i < 26; i++) {
                if(current.children[i] != null) {
                    ans.append((char)(i + 'a'));
                    current = current.children[i];
                    break;
                }
            }
        }

        return ans.toString();
    }
}

class Solution {

    class Node {
        Node[] children = new Node[26];
        String word;
    }

    List<String> result = new ArrayList<>();

    public List<String> findWords(char[][] board, String[] words) {

        Node root = new Node();

        // Build Trie using all words
        for(String word : words) {
            insert(root, word);
        }

        // Start DFS from every cell
        for(int i = 0; i < board.length; i++) {
            for(int j = 0; j < board[0].length; j++) {
                dfs(board, i, j, root);
            }
        }

        return result;
    }

    private void insert(Node root, String word) {

        Node current = root;

        for(char ch : word.toCharArray()) {
            int index = ch - 'a';

            if(current.children[index] == null) {
                current.children[index] = new Node();
            }

            current = current.children[index];
        }

        // Store completed word at ending node
        current.word = word;
    }

    private void dfs(char[][] board, int row, int col, Node node) {

        // Boundary check
        if(row < 0 || col < 0 || row >= board.length || col >= board[0].length) {
            return;
        }

        char ch = board[row][col];

        // Already visited or prefix does not exist
        if(ch == '#' || node.children[ch - 'a'] == null) {
            return;
        }

        Node next = node.children[ch - 'a'];

        // Complete word found
        if(next.word != null) {
            result.add(next.word);
            next.word = null;
        }

        // Mark visited
        board[row][col] = '#';

        dfs(board, row + 1, col, next);
        dfs(board, row - 1, col, next);
        dfs(board, row, col + 1, next);
        dfs(board, row, col - 1, next);

        // Restore original character
        board[row][col] = ch;
    }
}
